// scripts/generate-bundled-skills.ts — embeds src/skills/bundled/<name>/** into
// src/skills/bundled.generated.ts so the skills ship inside the built package
// (tsup bundles TypeScript, not loose files). Run after editing a bundled skill:
//   npm run generate:bundled-skills
// src/skills/bundled.test.ts fails when the generated file is stale.
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative, resolve } from "node:path";

// Resolved from the working directory (the backend root) rather than
// import.meta: the test suite imports this module under ts-jest (CommonJS).
const ROOT = resolve(process.cwd(), "src", "skills", "bundled");
const OUT = join(ROOT, "..", "bundled.generated.ts");

function walk(dir: string): string[] {
  return readdirSync(dir)
    .sort()
    .flatMap((name) => {
      const p = join(dir, name);
      return statSync(p).isDirectory() ? walk(p) : [p];
    });
}

export function collectBundledSkills(root = ROOT): Array<{ name: string; files: Record<string, string> }> {
  return readdirSync(root)
    .filter((name) => statSync(join(root, name)).isDirectory())
    .sort()
    .map((name) => {
      const files: Record<string, string> = {};
      for (const file of walk(join(root, name))) {
        files[relative(join(root, name), file).split("\\").join("/")] = readFileSync(file).toString("base64");
      }
      return { name, files };
    });
}

export function renderGenerated(skills: ReturnType<typeof collectBundledSkills>): string {
  return (
    "// GENERATED by scripts/generate-bundled-skills.ts from src/skills/bundled/<name>/** — do not edit.\n" +
    "// Files are base64 so the content survives tsup untouched (the HTML template carries backticks and ${}).\n" +
    "export const BUNDLED_SKILLS: ReadonlyArray<{ name: string; files: Record<string, string> }> = " +
    JSON.stringify(skills, null, 2) +
    ";\n"
  );
}

if (process.argv[1] && process.argv[1].endsWith("generate-bundled-skills.ts")) {
  const skills = collectBundledSkills();
  writeFileSync(OUT, renderGenerated(skills));
  console.log(`bundled skills: ${skills.map((s) => `${s.name} (${Object.keys(s.files).length} files)`).join(", ")} → ${relative(process.cwd(), OUT)}`);
}
